"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Switch: generated by UIX from the design system. Same variants and sizes as the Figma component.

const switchVariants = cva(
  "relative inline-flex shrink-0 cursor-pointer appearance-none items-center transition-colors bg-muted hover:bg-line-strong checked:bg-brand checked:hover:bg-brand-hover after:absolute after:rounded-full after:shadow-[0_1px_2px_rgb(0_0_0/0.15)] after:transition-transform after:bg-surface focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:cursor-not-allowed disabled:bg-disabled checked:disabled:bg-disabled rounded-full",
  {
    variants: {
      size: {
        sm: "w-[36px] h-5 after:size-4 after:top-[2px] after:left-[2px] checked:after:translate-x-[16px]",
        md: "w-[44px] h-6 after:size-5 after:top-[2px] after:left-[2px] checked:after:translate-x-[20px]",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

const switchLabelText: Record<string, string> = {"sm":"text-body-small","md":"text-body-medium"};

export interface SwitchProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size">,
    VariantProps<typeof switchVariants> {
  label?: React.ReactNode;
}

const Switch = React.forwardRef<HTMLInputElement, SwitchProps>(
  ({ className, size, label, ...props }, ref) => {
    const control = (
      <input ref={ref} type="checkbox" role="switch" data-slot="switch" data-kind="toggle" className={cn(switchVariants({ size }), className)} {...props} />
    );
    return (
      label ? (
        <label className={cn("inline-flex cursor-pointer items-center gap-2 text-fg-primary has-[:disabled]:cursor-not-allowed has-[:disabled]:text-fg-disabled", switchLabelText[size ?? "md"])}>
          {control}
          <span>{label}</span>
        </label>
      ) : (
        control
      )
    );
  },
);
Switch.displayName = "Switch";

export { Switch, switchVariants };
